/**
 * Registers a handler for one event type. Call the return value to detach.
 *
 * The handler set is copy-on-write: a subscribe that happens while `emit()` is
 * walking the set (a handler that attaches another handler) never mutates the
 * collection being iterated. Detaching is copy-on-write too, and it always
 * works on the set that is current at detach time: a later subscribe replaces
 * the set, so deleting from the one captured at attach time would leave the
 * handler attached.
 */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const fn = handler as EventHandler<TaskflowEventType>;
  const set: HandlerSet = new Set(handlers.get(type));
  set.add(fn);
  handlers.set(type, set);
  return () => {
    const current = handlers.get(type);
    if (!current?.has(fn)) return;
    const next: HandlerSet = new Set(current);
    next.delete(fn);
    handlers.set(type, next);
  };
}

