/**
 * The wiring the ops console and the dev hot reload drive: detach, re-attach,
 * repeat. Every cycle must leave exactly one live copy of each side effect —
 * webhook deliveries, audit rows and usage increments — while in-app
 * notifications, which are attached at module load, keep flowing throughout.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { getDb, webhookDeliveries } from "@/server/db";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { listActivity } from "@/server/services/activity-service";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import { listNotifications } from "@/server/services/notification-service";
import * as issueService from "@/server/services/issue-service";
import { getUsage } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

const AUDITED = ["issue.created", "issue.status_changed", "issue.assigned"] as const;

interface Counts {
  audit: number;
  deliveries: number;
  issuesUsed: number;
  assignedNotifications: number;
}

/** Side effects that the detachable handlers are responsible for. */
async function counts(): Promise<Counts> {
  const orgId = tenant.org.id;
  const audit = await listActivity(tenant.actors.owner, {
    orgId,
    action: [...AUDITED],
    limit: 100,
    cursor: null,
  });
  const notifications = await listNotifications(tenant.actors.owner, {
    orgId,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_assigned"],
    limit: 100,
    cursor: null,
  });
  const usage = await getUsage(tenant.actors.owner, orgId);
  const deliveries = getDb()
    .select()
    .from(webhookDeliveries)
    .all()
    .filter((row) => row.orgId === orgId);

  return {
    audit: audit.total,
    deliveries: deliveries.length,
    issuesUsed: usage.issuesUsed,
    assignedNotifications: notifications.total,
  };
}

/** Field-by-field difference between two snapshots. */
function delta(before: Counts, after: Counts): Counts {
  return {
    audit: after.audit - before.audit,
    deliveries: after.deliveries - before.deliveries,
    issuesUsed: after.issuesUsed - before.issuesUsed,
    assignedNotifications: after.assignedNotifications - before.assignedNotifications,
  };
}

const ZERO: Counts = { audit: 0, deliveries: 0, issuesUsed: 0, assignedNotifications: 0 };

/** Creates an issue and assigns it, so one action touches every side effect. */
async function createAndAssign(title: string): Promise<void> {
  const issue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, {
      title,
      assigneeId: null,
    }),
  );
  await issueService.assignIssue(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    assigneeId: tenant.userIds.admin,
  });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("registry", "growth");

  await webhookRepo.insertEndpoint(
    {
      orgId: tenant.org.id,
      url: "https://hooks.example.test/subscribed",
      eventTypes: ["issue.created", "issue.status_changed"],
    },
    "secret-subscribed",
  );
  await webhookRepo.insertEndpoint(
    {
      orgId: tenant.org.id,
      url: "https://hooks.example.test/unrelated",
      eventTypes: ["comment.created"],
    },
    "secret-unrelated",
  );

  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

describe("services/event-registry", () => {
  it("produces exactly one delivery, audit row and usage increment per action after repeated detach/re-attach cycles", async () => {
    for (let cycle = 0; cycle < 3; cycle += 1) {
      unregisterEventHandlers();
      registerEventHandlers();
    }

    const before = await counts();
    await createAndAssign("After the cycles");
    const after = delta(before, await counts());

    // Two audited actions (create + assign), one subscribed endpoint, one
    // usage increment for the created issue, one in-app notification.
    expect(after).toEqual({
      audit: 2,
      deliveries: 1,
      issuesUsed: 1,
      assignedNotifications: 1,
    });
  });

  it("registering again without detaching first is a no-op", async () => {
    registerEventHandlers();
    registerEventHandlers();

    const before = await counts();
    await createAndAssign("Registered twice");
    const after = delta(before, await counts());

    expect(after).toEqual({
      audit: 2,
      deliveries: 1,
      issuesUsed: 1,
      assignedNotifications: 1,
    });
  });

  it("produces no webhooks, audit rows or usage while detached, and notifications keep flowing", async () => {
    unregisterEventHandlers();

    const before = await counts();
    await createAndAssign("While detached");
    const during = delta(before, await counts());

    expect(during).toEqual({
      audit: 0,
      deliveries: 0,
      issuesUsed: 0,
      assignedNotifications: 1,
    });

    registerEventHandlers();

    const reattached = await counts();
    await createAndAssign("Back online");
    const resumed = delta(reattached, await counts());

    expect(resumed).toEqual({
      audit: 2,
      deliveries: 1,
      issuesUsed: 1,
      assignedNotifications: 1,
    });
    expect(ZERO).toEqual({ audit: 0, deliveries: 0, issuesUsed: 0, assignedNotifications: 0 });
  });
});

