import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import { listNotifications } from "@/server/services/notification-service";
import * as issueService from "@/server/services/issue-service";
import { getUsage } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

const AUDITED = ["issue.created", "issue.status_changed", "issue.assigned"] as const;

interface Counts {
  audit: number;
  deliveries: number;
  issuesUsed: number;
  assignedNotifications: number;
}

/** Side effects that the detachable handlers are responsible for. */
async function counts(): Promise<Counts> {
  const orgId = tenant.org.id;
  const audit = await listActivity(tenant.actors.owner, {
    orgId,
    action: [...AUDITED],
    limit: 100,
    cursor: null,
  });
  const notifications = await listNotifications(tenant.actors.owner, {
    orgId,
    recipientId: tenant.userIds.admin,
    unreadOnly: false,
    kind: ["issue_assigned"],
    limit: 100,
    cursor: null,
  });
  const usage = await getUsage(tenant.actors.owner, orgId);
  const deliveries = getDb()
    .select()
    .from(webhookDeliveries)
    .where(eq(webhookDeliveries.orgId, orgId))
    .all();

  return {
    audit: audit.total,
    deliveries: deliveries.length,
    issuesUsed: usage.issuesUsed,
    assignedNotifications: notifications.total,
  };
}

/** Field-by-field difference between two snapshots. */
function delta(before: Counts, after: Counts): Counts {
  return {
    audit: after.audit - before.audit,
    deliveries: after.deliveries - before.deliveries,
    issuesUsed: after.issuesUsed - before.issuesUsed,
    assignedNotifications: after.assignedNotifications - before.assignedNotifications,
  };
}

const ZERO: Counts = { audit: 0, deliveries: 0, issuesUsed: 0, assignedNotifications: 0 };

/** Creates an issue and assigns it, so one action touches every side effect. */
async function createAndAssign(title: string): Promise<void> {
  const issue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, {
      title,
      assigneeId: null,
    }),
  );
  await issueService.assignIssue(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    assigneeId: tenant.userIds.admin,
  });
}

