    registerEventHandlers();
    registerEventHandlers();

    const before = await counts();
    await createAndAssign("Registered twice");
    const after = delta(before, await counts());

    expect(after).toEqual({
      audit: 2,
      deliveries: 1,
      issuesUsed: 1,
      assignedNotifications: 1,
    });
  });

  it("produces no webhooks, audit rows or usage while detached, and notifications keep flowing", async () => {
    unregisterEventHandlers();

    const before = await counts();
    await createAndAssign("While detached");
    const during = delta(before, await counts());

    expect(during).toEqual({
      audit: 0,
      deliveries: 0,
      issuesUsed: 0,
      assignedNotifications: 1,
    });

    registerEventHandlers();

    const reattached = await counts();
    await createAndAssign("Back online");
    const resumed = delta(reattached, await counts());

    expect(resumed).toEqual({
      audit: 2,
      deliveries: 1,
      issuesUsed: 1,
      assignedNotifications: 1,
    });
    expect(ZERO).toEqual({ audit: 0, deliveries: 0, issuesUsed: 0, assignedNotifications: 0 });
  });
});

